      '\u0646\u0648\u0634\u06cc\u062f\u0646\u06cc': 'Drinks',
      '\u0646\u0648\u0639': 'Type',
      '\u0646\u0648\u0639 \u062a\u063a\u06cc\u06cc\u0631 \u0631\u0627 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0646':
        'Choose change type',
      '\u0646\u0648\u0639 \u062a\u063a\u06cc\u06cc\u0631 \u0631\u0627 \u0645\u0634\u062e\u0635 \u06a9\u0646':
        'Specify change type',
      '\u0646\u0648\u0639 \u0648 \u0627\u0633\u0645 \u06a9\u0627\u0644\u0627 \u0631\u0627 \u0641\u06cc\u0644\u062a\u0631 \u06a9\u0646.':
        'Filter by item type and name.',
