        'Sale receipts',
      '\u0631\u0633\u06cc\u062f \u0641\u0631\u0648\u0634': 'Sale receipt',
      '\u0631\u0633\u06cc\u062f \u062e\u0631\u06cc\u062f': 'Purchase receipt',
      '\u0631\u0633\u06cc\u062f \u062e\u0631\u06cc\u062f {no}':
        'Purchase receipt {no}',
